metadata.normalizerSource:
import re

def reason_parts(message):
 s=re.sub(r'^.*?lowering trap: ','',message,flags=re.S)
 # A body-refusal list prefixes each diagnostic with its source node. A
 # semicolon within one diagnostic (for example parseInt) stays in that reason.
 marker='\x1e'
 s=re.sub(r'(?:^|;\s*)node \d+ \([^)]*\):\s*',marker,s)
 result=[]
 for part in s.split(marker):
  part=re.sub(r'\s*\[[^\]]*(?:node \d+|@)[^\]]*\]','',part)
  part=re.sub(r'/work/\.cache/measurement/all-[^/]+/[^/]+/','',part)
  part=re.sub(r'((?:src|test|runtime)/[^\s:;\]\)]+):\d+:\d+',r'\1',part)
  part=re.sub(r'0x[0-9a-fA-F]+','<address>',part)
  part=re.sub(r'\b(?:z(?:cl|if|cx)_[a-z0-9_]*?)_[0-9a-f]{12,16}\b',lambda m:re.sub(r'_[0-9a-f]{12,16}$','_<hash>',m[0]),part,flags=re.I)
  part=re.sub(r'(?<=\.abap):\d+\b',':<line>',part)
  part=part.strip()
  if part:result.append(part)
 return sorted(set(result))

def normalize(message):return '; '.join(reason_parts(message))

def zone(reason):
 if re.search(r'chai|json|json5|string[.]|xml|harness|hook|mocha|regexp|reg[_e]|stringify|parseint|parsefloat|padstart|sha1|splitregex',reason,re.I):return 'abapiti'
 return 'dell'

if __name__=='__main__':
 import json,collections,pathlib
 for p in pathlib.Path('.cache/measurement').glob('all-*/go-*.json'):
  x=json.loads(p.read_text());c=collections.Counter(normalize(r['message']) for r in x['results'] if r['status']=='trapped');print(p.name,c.most_common(5))

